"use client"

import * as React from "react"

import { Sidebar01Shell } from "@/components/sidebar-01/shell"

/**
 * 页面入口。nav-data.ts 里的地址只是示例（这些路由并不存在），
 * 所以这里拦截跳转，用本地状态模拟「当前页」，点侧栏就能看到高亮、展开和面包屑的变化。
 *
 * 接入真实路由时：把 navigation 换成 Next 的 Link 和 usePathname，并把 nav-data.ts 改成你自己的地址：
 *
 *   import Link from "next/link"
 *   import { usePathname } from "next/navigation"
 *   <Sidebar01Shell currentHref={usePathname()} linkComponent={Link} />
 */
export default function Sidebar01Page() {
  const [href, setHref] = React.useState("/content/articles")
  return (
    <Sidebar01Shell
      currentHref={href}
      navigation={{ intercept: true, onNavigate: ({ href }) => setHref(href) }}
    />
  )
}

"use client"

import * as React from "react"
import {
  LayersIcon,
  PanelLeftCloseIcon,
  PanelLeftOpenIcon,
  SearchIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInput,
  SidebarMenu,
  SidebarRail,
  useSidebar,
} from "@/components/ui/sidebar"
import { TooltipProvider } from "@/components/ui/tooltip"
import { DEFAULT_LABELS, type Sidebar01Labels } from "./config"
import {
  Sidebar01Context,
  useSidebar01,
  type Sidebar01ContextValue,
} from "./context"
import { NavAnchor } from "./nav-anchor"
import { DEFAULT_BRAND, DEFAULT_FOOTER_ITEMS, DEFAULT_GROUPS } from "./nav-data"
import { NavItem } from "./nav-parts"
import type {
  Sidebar01Brand,
  Sidebar01Group,
  Sidebar01Item,
  Sidebar01Navigation,
} from "./types"
import {
  collectHrefs,
  filterGroups,
  findActiveHref,
  findActiveParentId,
  formatLabel,
} from "./utils"

type Sidebar01Props = Omit<
  React.ComponentProps<typeof Sidebar>,
  "collapsible" | "children"
> & {
  /**
   * 导航分组
   * @default 示例数据（nav-data.ts）
   */
  groups?: Sidebar01Group[]
  /**
   * 固定在底部的次要入口，只放链接
   * @default 帮助中心、设置
   */
  footerItems?: Sidebar01Item[]
  /** 底部插槽，排在 footerItems 之后：放当前用户、退出登录这类不是链接的内容 */
  footer?: React.ReactNode
  /** 品牌：方形 logo + 名称 */
  brand?: Sidebar01Brand
  /**
   * 是否显示导航搜索框；条目很少时可以关掉
   * @default true
   */
  searchable?: boolean
  /** 当前地址（pathname），用来高亮当前项并默认展开它所在的父项 */
  currentHref?: string
  /**
   * 手风琴：同一时间只展开一个父项
   * @default true
   */
  accordion?: boolean
  /** 链接行为：点击回调与拦截跳转，同 app-shell-01 的 NavLinkBehavior */
  navigation?: Sidebar01Navigation
  /**
   * 链接组件，换成 Next 的 Link 即可走客户端路由
   * @default "a"
   */
  linkComponent?: React.ElementType
  /** 覆盖默认文案 */
  labels?: Partial<Sidebar01Labels>
}

/** 品牌方块：默认图标可通过 brand.logo 替换。 */
function BrandLogo({ logo }: { logo?: React.ReactNode }) {
  return (
    <span
      data-slot="sidebar-01-logo"
      className="flex size-8 shrink-0 items-center justify-center rounded-md bg-sidebar-primary text-sidebar-primary-foreground [&_svg:not([class*='size-'])]:size-4"
    >
      {logo ?? <LayersIcon />}
    </span>
  )
}

function Sidebar01Header({
  brand,
  searchable,
  query,
  onQueryChange,
}: {
  brand: Sidebar01Brand
  searchable: boolean
  query: string
  onQueryChange: (query: string) => void
}) {
  const { labels } = useSidebar01()
  const { toggleSidebar } = useSidebar()
  const name = (
    <>
      <BrandLogo logo={brand.logo} />
      <span className="truncate text-sm font-semibold">{brand.name}</span>
    </>
  )
  return (
    <>
      {/* 品牌带高 56px（h-14），底线与右侧顶栏的底线连成一条 */}
      <SidebarHeader className="h-14 shrink-0 justify-center border-b border-sidebar-border">
        <div className="flex items-center gap-2">
          {brand.href ? (
            <NavAnchor
              href={brand.href}
              className="flex min-w-0 flex-1 items-center gap-2 rounded-md outline-hidden group-data-[collapsible=icon]:hidden focus-visible:ring-2 focus-visible:ring-sidebar-ring"
            >
              {name}
            </NavAnchor>
          ) : (
            <div className="flex min-w-0 flex-1 items-center gap-2 group-data-[collapsible=icon]:hidden">
              {name}
            </div>
          )}
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label={labels.collapse}
            onClick={toggleSidebar}
            className="group-data-[collapsible=icon]:hidden"
          >
            <PanelLeftCloseIcon />
          </Button>
          {/* 收起后图标栏只有 32px：logo 本身就是展开按钮，悬停时换成展开图标 */}
          <Button
            variant="ghost"
            size="icon"
            aria-label={labels.expand}
            onClick={toggleSidebar}
            className="group/expand relative hidden p-0 group-data-[collapsible=icon]:flex"
          >
            <span className="transition-opacity group-hover/expand:opacity-0 group-focus-visible/expand:opacity-0">
              <BrandLogo logo={brand.logo} />
            </span>
            <PanelLeftOpenIcon className="absolute opacity-0 transition-opacity group-hover/expand:opacity-100 group-focus-visible/expand:opacity-100" />
          </Button>
        </div>
      </SidebarHeader>
      {searchable ? (
        <div className="relative shrink-0 border-b border-sidebar-border p-2 group-data-[collapsible=icon]:hidden">
          <SearchIcon
            aria-hidden
            className="pointer-events-none absolute top-1/2 left-4.5 size-4 -translate-y-1/2 text-muted-foreground"
          />
          <SidebarInput
            type="search"
            aria-label={labels.search}
            placeholder={labels.searchPlaceholder}
            value={query}
            onChange={(event) => onQueryChange(event.target.value)}
            className="pl-8 [&::-webkit-search-cancel-button]:appearance-none"
          />
        </div>
      ) : null}
    </>
  )
}

/**
 * 可收起侧栏：基于 shadcn 官方 Sidebar（`collapsible="icon"`），补上收起后的浮出子菜单。
 * 必须放在 `SidebarProvider` 内；移动端沿用官方的 Sheet 抽屉。
 */
function Sidebar01({
  groups = DEFAULT_GROUPS,
  footerItems = DEFAULT_FOOTER_ITEMS,
  footer,
  brand = DEFAULT_BRAND,
  searchable = true,
  currentHref,
  accordion = true,
  navigation,
  linkComponent = "a",
  labels: labelsProp,
  className,
  ...props
}: Sidebar01Props) {
  const labels = React.useMemo(
    () => ({ ...DEFAULT_LABELS, ...labelsProp }),
    [labelsProp],
  )
  const activeHref = React.useMemo(
    () => findActiveHref(collectHrefs(groups, footerItems), currentHref),
    [groups, footerItems, currentHref],
  )
  const activeParentId = findActiveParentId(groups, activeHref)

  // 当前页面所在的父项初始就展开；地址变化落到别的父项时也跟着展开
  const [expandedIds, setExpandedIds] = React.useState<string[]>(
    activeParentId ? [activeParentId] : [],
  )
  const [lastActiveParentId, setLastActiveParentId] =
    React.useState(activeParentId)
  if (activeParentId !== lastActiveParentId) {
    setLastActiveParentId(activeParentId)
    if (activeParentId) {
      setExpandedIds((current) => {
        if (accordion) return [activeParentId]
        return current.includes(activeParentId)
          ? current
          : [...current, activeParentId]
      })
    }
  }

  const setExpanded = React.useCallback(
    (id: string, open: boolean) => {
      setExpandedIds((current) => {
        if (accordion) return open ? [id] : current.filter((x) => x !== id)
        return open
          ? current.includes(id)
            ? current
            : [...current, id]
          : current.filter((x) => x !== id)
      })
    },
    [accordion],
  )

  const [query, setQuery] = React.useState("")
  const visibleGroups = React.useMemo(
    () => filterGroups(groups, query),
    [groups, query],
  )
  const searching = query.trim() !== ""

  const context = React.useMemo<Sidebar01ContextValue>(
    () => ({
      labels,
      linkComponent,
      navigation,
      activeHref,
      expandedIds,
      searching,
      setExpanded,
    }),
    [
      labels,
      linkComponent,
      navigation,
      activeHref,
      expandedIds,
      searching,
      setExpanded,
    ],
  )

  return (
    <Sidebar01Context.Provider value={context}>
      <TooltipProvider>
        <Sidebar
          collapsible="icon"
          className={cn("border-sidebar-border", className)}
          {...props}
        >
          <Sidebar01Header
            brand={brand}
            searchable={searchable}
            query={query}
            onQueryChange={setQuery}
          />
          <SidebarContent data-slot="sidebar-01-content">
            <nav aria-label={labels.navLabel}>
              {visibleGroups.map((group) => (
                <SidebarGroup key={group.id}>
                  <SidebarGroupLabel>{group.label}</SidebarGroupLabel>
                  <SidebarGroupContent>
                    <SidebarMenu>
                      {group.items.map((item) => (
                        <NavItem key={item.id} item={item} />
                      ))}
                    </SidebarMenu>
                  </SidebarGroupContent>
                </SidebarGroup>
              ))}
            </nav>
            <div role="status" className="group-data-[collapsible=icon]:hidden">
              {searching && visibleGroups.length === 0 ? (
                <p className="px-4 py-6 text-center text-sm text-muted-foreground">
                  {formatLabel(labels.empty, { query: query.trim() })}
                </p>
              ) : null}
            </div>
          </SidebarContent>
          {footerItems.length > 0 || footer ? (
            <SidebarFooter className="border-t border-sidebar-border">
              {footerItems.length > 0 ? (
                <nav aria-label={labels.footerLabel}>
                  <SidebarMenu>
                    {footerItems.map((item) => (
                      <NavItem key={item.id} item={item} />
                    ))}
                  </SidebarMenu>
                </nav>
              ) : null}
              {footer}
            </SidebarFooter>
          ) : null}
          <SidebarRail />
        </Sidebar>
      </TooltipProvider>
    </Sidebar01Context.Provider>
  )
}

export { Sidebar01 }
export type { Sidebar01Props }

"use client"

import * as React from "react"
import { ChevronRightIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  useSidebar,
} from "@/components/ui/sidebar"
import { ROW_CLASS, SUB_ROW_CLASS } from "./config"
import { useSidebar01 } from "./context"
import { NavAnchor } from "./nav-anchor"
import type { Sidebar01Item, Sidebar01SubItem } from "./types"
import { normalizeHref } from "./utils"

/** 子项左侧的一小段横线，连到父级的竖向引导线上（竖线 = 容器左边框）。 */
const CONNECTOR_CLASS =
  "before:pointer-events-none before:absolute before:top-1/2 before:-left-2.5 before:h-px before:w-2.5 before:bg-sidebar-border"

function isActiveSub(sub: Sidebar01SubItem, activeHref?: string) {
  return activeHref !== undefined && normalizeHref(sub.href) === activeHref
}

function SubBadge({ children }: { children: React.ReactNode }) {
  return (
    <span
      data-slot="sidebar-01-sub-badge"
      className="ms-auto shrink-0 text-xs text-sidebar-foreground/70 tabular-nums"
    >
      {children}
    </span>
  )
}

/** 没有子项的条目；收起后悬停或聚焦时用 Tooltip 显示名称。 */
function NavLeaf({ item }: { item: Sidebar01Item }) {
  const { activeHref } = useSidebar01()
  const isActive =
    activeHref !== undefined &&
    item.href !== undefined &&
    normalizeHref(item.href) === activeHref
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        tooltip={item.label}
        isActive={isActive}
        className={cn(ROW_CLASS, item.badge !== undefined && "pr-9")}
        render={
          <NavAnchor
            href={item.href ?? "#"}
            aria-current={isActive ? "page" : undefined}
          />
        }
      >
        <item.icon />
        <span>{item.label}</span>
      </SidebarMenuButton>
      {item.badge !== undefined ? (
        <SidebarMenuBadge className="top-1/2! -translate-y-1/2">
          {item.badge}
        </SidebarMenuBadge>
      ) : null}
    </SidebarMenuItem>
  )
}

/** 展开态的父项：Collapsible + 带引导线的子项列表。 */
function ExpandedParent({ item }: { item: Sidebar01Item }) {
  const { activeHref, expandedIds, searching, setExpanded } = useSidebar01()
  const subs = item.items ?? []
  const open = searching || expandedIds.includes(item.id)
  const hasActive = subs.some((sub) => isActiveSub(sub, activeHref))
  return (
    <SidebarMenuItem>
      <Collapsible
        open={open}
        onOpenChange={(next) => setExpanded(item.id, next)}
      >
        <CollapsibleTrigger
          render={
            <SidebarMenuButton
              className={cn(ROW_CLASS, hasActive && "font-medium")}
            />
          }
        >
          <item.icon />
          {/* 有计数时给绝对定位的徽标让出位置 */}
          <span className={cn("truncate", item.badge !== undefined && "pe-8")}>
            {item.label}
          </span>
          <ChevronRightIcon
            aria-hidden
            className={cn(
              "ms-auto transition-transform duration-200 motion-reduce:transition-none",
              open && "rotate-90",
            )}
          />
        </CollapsibleTrigger>
        {item.badge !== undefined ? (
          <SidebarMenuBadge className="top-4! right-7 -translate-y-1/2 pointer-coarse:top-5!">
            {item.badge}
          </SidebarMenuBadge>
        ) : null}
        <CollapsibleContent className="h-(--collapsible-panel-height) overflow-hidden transition-[height] duration-200 data-ending-style:h-0 data-starting-style:h-0 motion-reduce:transition-none">
          <SidebarMenuSub>
            {subs.map((sub) => {
              const isActive = isActiveSub(sub, activeHref)
              return (
                <SidebarMenuSubItem key={sub.id} className={CONNECTOR_CLASS}>
                  <SidebarMenuSubButton
                    isActive={isActive}
                    className={cn(SUB_ROW_CLASS, isActive && "font-medium")}
                    render={
                      <NavAnchor
                        href={sub.href}
                        aria-current={isActive ? "page" : undefined}
                      />
                    }
                  >
                    <span>{sub.label}</span>
                    {sub.badge !== undefined ? (
                      <SubBadge>{sub.badge}</SubBadge>
                    ) : null}
                  </SidebarMenuSubButton>
                </SidebarMenuSubItem>
              )
            })}
          </SidebarMenuSub>
        </CollapsibleContent>
      </Collapsible>
    </SidebarMenuItem>
  )
}

/**
 * 收起态的父项：官方 Sidebar 收起后子菜单会被隐藏，这里用 Menu 浮层补上。
 * 悬停（带安全三角，鼠标移向浮层途中不会闪退）、点击、Enter / Space / → 都能打开；
 * 方向键在子项间移动，Esc 关闭并把焦点还给图标，点子项跳转并关闭。
 */
function CollapsedParent({ item }: { item: Sidebar01Item }) {
  const { activeHref } = useSidebar01()
  const subs = item.items ?? []
  const hasActive = subs.some((sub) => isActiveSub(sub, activeHref))

  // Menu 默认只响应 Enter / Space / ↑ / ↓，补上 →（侧栏子菜单向右展开）
  function handleKeyDown(event: React.KeyboardEvent<HTMLElement>) {
    if (
      event.key === "ArrowRight" &&
      event.currentTarget.getAttribute("aria-expanded") !== "true"
    ) {
      event.preventDefault()
      event.currentTarget.click()
    }
  }

  return (
    <SidebarMenuItem>
      <DropdownMenu>
        <DropdownMenuTrigger
          openOnHover
          delay={60}
          closeDelay={120}
          onKeyDown={handleKeyDown}
          render={
            <SidebarMenuButton
              isActive={hasActive}
              className={cn(
                ROW_CLASS,
                "data-popup-open:bg-sidebar-accent data-popup-open:text-sidebar-accent-foreground",
              )}
            />
          }
        >
          <item.icon />
          <span>{item.label}</span>
        </DropdownMenuTrigger>
        <DropdownMenuContent
          side="right"
          align="start"
          sideOffset={8}
          alignOffset={-4}
          className="w-52 min-w-52 bg-sidebar text-sidebar-foreground shadow-sm ring-sidebar-border"
        >
          <DropdownMenuGroup>
            <DropdownMenuLabel className="px-2 py-1.5 text-sm font-medium text-sidebar-foreground">
              {item.label}
            </DropdownMenuLabel>
            <div
              role="presentation"
              className="mx-3.5 flex flex-col gap-1 border-l border-sidebar-border px-2.5 pt-0.5 pb-1"
            >
              {subs.map((sub) => {
                const isActive = isActiveSub(sub, activeHref)
                return (
                  <DropdownMenuItem
                    key={sub.id}
                    data-active={isActive || undefined}
                    aria-current={isActive ? "page" : undefined}
                    className={cn(
                      "h-7 px-2 focus:bg-sidebar-accent focus:text-sidebar-accent-foreground data-active:bg-sidebar-accent data-active:font-medium data-active:text-sidebar-accent-foreground",
                      SUB_ROW_CLASS,
                      CONNECTOR_CLASS,
                    )}
                    render={<NavAnchor href={sub.href} />}
                  >
                    <span className="truncate">{sub.label}</span>
                    {sub.badge !== undefined ? (
                      <SubBadge>{sub.badge}</SubBadge>
                    ) : null}
                  </DropdownMenuItem>
                )
              })}
            </div>
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    </SidebarMenuItem>
  )
}

/** 按当前侧栏状态选择渲染方式：收起（仅桌面）用浮层，其余用折叠列表。 */
function NavItem({ item }: { item: Sidebar01Item }) {
  const { isMobile, state } = useSidebar()
  if (!item.items?.length) return <NavLeaf item={item} />
  return state === "collapsed" && !isMobile ? (
    <CollapsedParent item={item} />
  ) : (
    <ExpandedParent item={item} />
  )
}

export { NavItem, NavLeaf }

"use client"

import * as React from "react"

import { useSidebar } from "@/components/ui/sidebar"
import { useSidebar01 } from "./context"

/**
 * 导航链接：默认渲染 `<a>`，可通过 Sidebar01 的 `linkComponent` 换成 Next 的 Link。
 * 保留 Cmd/Ctrl 点击等原生行为，只处理普通左键点击；手机上点击后自动关闭抽屉。
 * 通过 `render={<NavAnchor href="…" />}` 交给侧栏按钮或浮层条目使用。
 */
function NavAnchor({
  href,
  onClick,
  ...props
}: React.ComponentProps<"a"> & { href: string }) {
  const { linkComponent: LinkComponent, navigation } = useSidebar01()
  const { isMobile, setOpenMobile } = useSidebar()

  function handleClick(event: React.MouseEvent<HTMLAnchorElement>) {
    onClick?.(event)
    if (
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey
    ) {
      return
    }
    if (navigation?.intercept) event.preventDefault()
    navigation?.onNavigate?.({ href })
    if (isMobile) setOpenMobile(false)
  }

  return (
    <LinkComponent
      data-slot="sidebar-01-link"
      href={href}
      onClick={handleClick}
      // 拦截跳转时地址只是标识（预览里这些路由并不存在），换成 Link 时不要预取
      {...(navigation?.intercept && LinkComponent !== "a"
        ? { prefetch: false }
        : null)}
      {...props}
    />
  )
}

export { NavAnchor }

"use client"

import * as React from "react"

import type { Sidebar01Labels } from "./config"
import type { Sidebar01Navigation } from "./types"

type Sidebar01ContextValue = {
  labels: Sidebar01Labels
  linkComponent: React.ElementType
  navigation?: Sidebar01Navigation
  /** 与当前地址匹配的 href（已规范化） */
  activeHref?: string
  /** 展开着的父项 id */
  expandedIds: string[]
  /** 搜索中：命中的父项一律展开，忽略 expandedIds */
  searching: boolean
  setExpanded: (id: string, open: boolean) => void
}

const Sidebar01Context = React.createContext<Sidebar01ContextValue | null>(null)

function useSidebar01() {
  const context = React.useContext(Sidebar01Context)
  if (!context) {
    throw new Error("Sidebar01 的子组件必须放在 Sidebar01 内部。")
  }
  return context
}

export { Sidebar01Context, useSidebar01 }
export type { Sidebar01ContextValue }

import {
  ChartColumnIcon,
  FileTextIcon,
  ImagesIcon,
  LayoutDashboardIcon,
  LifeBuoyIcon,
  MessageSquareIcon,
  PlugIcon,
  SettingsIcon,
  ShieldCheckIcon,
  TagsIcon,
  UsersIcon,
} from "lucide-react"

import type { Sidebar01Brand, Sidebar01Group, Sidebar01Item } from "./types"

/** 示例数据：一个内容运营后台。换成你自己的路由即可。 */
const DEFAULT_BRAND: Sidebar01Brand = { name: "内容工作台" }

const DEFAULT_GROUPS: Sidebar01Group[] = [
  {
    id: "content",
    label: "内容",
    items: [
      {
        id: "overview",
        label: "工作概览",
        icon: LayoutDashboardIcon,
        href: "/overview",
      },
      {
        id: "articles",
        label: "文章",
        icon: FileTextIcon,
        badge: 8,
        items: [
          { id: "all", label: "全部文章", href: "/content/articles" },
          { id: "drafts", label: "草稿箱", href: "/content/drafts", badge: 5 },
          { id: "review", label: "待审核", href: "/content/review", badge: 3 },
          { id: "archive", label: "已归档", href: "/content/archive" },
        ],
      },
      {
        id: "media",
        label: "媒体库",
        icon: ImagesIcon,
        items: [
          { id: "images", label: "图片", href: "/media/images" },
          { id: "videos", label: "视频", href: "/media/videos" },
          { id: "files", label: "文件", href: "/media/files" },
        ],
      },
      {
        id: "comments",
        label: "评论",
        icon: MessageSquareIcon,
        href: "/comments",
        badge: 12,
      },
    ],
  },
